def createGrid(k):
    # one L-shaped corridor has exactly one path: (0,0) -> (0,1) -> (1,1)
    if k == 1:
        return ["..", "#."]

    bits = bin(k)[2:]            # bits[0] is the leading 1
    T = len(bits) - 1            # number of doubling blocks
    # block t (t = 0 .. T-1) consumes bits[t + 1]
    # if that bit is 1 for block 0, make block 0 a 2x3 strip (3 paths) and shift the rest right
    delta = 1 if bits[1] == '1' else 0
    rows = 2 * T
    cols = 2 * T + delta
    g = [['#'] * cols for _ in range(rows)]

    # block 0 occupies rows 0..1 and columns 0..1 (plus column 2 when delta is 1)
    for r in range(2):
        for c in range(2 + delta):
            g[r][c] = '.'

    # blocks 1 .. T-1: free 2x2 squares with top-left corner (2t, 2t + delta)
    for t in range(1, T):
        top = 2 * t
        left = 2 * t + delta
        for r in range(top, top + 2):
            for c in range(left, left + 2):
                g[r][c] = '.'

    # link cell between block t and block t + 1
    for t in range(T - 1):
        g[2 * t + 1][2 * t + delta + 2] = '.'

    # corridors that inject one extra path into the lower-middle cell of block t
    for t in range(1, T):
        if bits[t + 1] == '1':
            # column 0 down to the corridor row, then right along row 2t + 1
            for r in range(2 * t + 2):
                g[r][0] = '.'
            for c in range(2 * t + delta):
                g[2 * t + 1][c] = '.'

    return [''.join(row) for row in g]
